/// <summary>
/// assiging return order components
/// </summary>
public class METSalesPriceComponents_Sales extends METSalesPriceComponents
{   
}

Method.Source:
/// <summary>
/// Query ranges
/// </summary>
/// <param name = "qbdsSalesLine">QueryBuildDataSource</param>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_metSalesTabel">METSalesTable</param>
/// <param name = "_metSalesPriceComponent">Sales price component QueryBuildDataSource</param>
public void queryRange(QueryBuildDataSource qbdsSalesLine, SalesLine _salesLine, METSalesTable _metSalesTabel, QueryBuildDataSource _metSalesPriceComponent)
{
    qbdsSalesLine.addRange(fieldNum(SalesLine, RecId)).value(any2Str(_salesLine.RecId));
}

/// <summary>
/// assig return values
/// </summary>
/// <param name = "_priceComponent">METSalesLinePriceComponent</param>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_tmpTable">METSalesLinePriceComponentTmp</param>
public void setValues(METSalesLinePriceComponent _priceComponent,
                       SalesLine _salesLine,
                       METSalesLinePriceComponentTmp _tmpTable,
                       SalesLine _orgSalesLine)
{
    METGrossWeight actualWeight;

    // Base value from price component
    tmpTable.Value = _priceComponent.Value;

    // Cache flags to avoid repeated static method calls
    boolean isCWItem = PdsGlobal::pdsIsCWItem(_salesLine.ItemId);
    boolean isPricedByWeight = METPricedByWeightCache::getPricedByWeightAttributeCached(_salesLine.ItemId);

    // If item is Catch Weight (CW), use actual weight from sales line
    if (isCWItem)
    {
        actualWeight = _salesLine.displayMETActualWeight();
    }

    // Retrieve physical dimensions (weight per UOM for site)
    METWHSPhysDimUOMSite metWHSPhysDimUOMSite;
    InventDim inventDim = _salesLine.inventDim();
    UnitOfMeasureSymbol unitSales = _salesLine.SalesUnit;

    select firstonly weight, NetWeight from metWHSPhysDimUOMSite
        where metWHSPhysDimUOMSite.ItemId == _salesLine.ItemId
        && metWHSPhysDimUOMSite.UOM == unitSales
        && metWHSPhysDimUOMSite.SiteId == inventDim.InventSiteId;

    // If item is priced by weight, calculate actual weight = NetWeight × SalesQty
    if (isPricedByWeight)
    {
        actualWeight = metWHSPhysDimUOMSite.NetWeight * _salesLine.SalesQty;
    }

    // If item is CW or priced by weight, check warehouse transactions
    if (isCWItem || isPricedByWeight)
    {
        WMSOrderTrans wmsOrderTrans;

        // Get warehouse transaction qty (only if expedition is complete or activated)
        select firstonly Qty from wmsOrderTrans
            where wmsOrderTrans.InventTransId == _salesLine.InventTransId
            && (wmsOrderTrans.expeditionStatus == WMSExpeditionStatus::Complete
               || wmsOrderTrans.expeditionStatus == WMSExpeditionStatus::Activated);

        if (wmsOrderTrans.Qty)
        {
            // If priced by weight but not CW, multiply qty by NetWeight
            actualWeight = (!isCWItem && isPricedByWeight)
            ? wmsOrderTrans.Qty * metWHSPhysDimUOMSite.NetWeight
            : wmsOrderTrans.Qty;
        }
    }

    // Final extended value calculation
    if (actualWeight)
    {
        tmpTable.ExtValue = tmpTable.Value * actualWeight;
    }
    else
    {
        // Fallback: use original sales line quantity
        tmpTable.ExtValue = tmpTable.Value * _orgSalesLine.SalesQty;
    }
}
